def grep(pattern, flags, files):
    flags = set(flags.split())
    show_line_numbers = "-n" in flags
    show_file_names = "-l" in flags
    ignore_case = "-i" in flags
    invert = "-v" in flags
    whole_line = "-x" in flags

    if ignore_case:
        pattern = pattern.lower()

    output = []
    files_with_match = set()
    for filename in files:
        with open(filename) as f:
            lines = f.readlines()

        for line_number, line in enumerate(lines, start=1):
            text = line.rstrip("\n")
            haystack = text.lower() if ignore_case else text
            matched = (
                haystack == pattern if whole_line else pattern in haystack
            )
            if matched != invert:
                if show_file_names:
                    if filename not in files_with_match:
                        files_with_match.add(filename)
                        output.append(filename + "\n")
                else:
                    prefix = ""
                    if len(files) > 1:
                        prefix += filename + ":"
                    if show_line_numbers:
                        prefix += str(line_number) + ":"
                    output.append(prefix + text + "\n")
    return "".join(output)

